{"title": "CDN 与隔离", "note": "清单里的库能加载，别的都被拦", "html": "<style>
  .line{margin:4px 0;font-size:var(--font-text-sm-size);color:var(--color-text-secondary)}
</style>
<div class="line" id="marker">lib:0</div>
<div class="line" id="fetch">fetch:pending</div>
<div class="line" id="api">api:pending</div>
<div class="line" id="ws">ws:pending</div>
<div class="line" id="parent">parent:pending</div>
<img id="extimg" src="https://evil.example/pixel.png" alt="外部图片">
<script src="https://cdn.jsdelivr.net/npm/t015-fake-lib/index.js"></script>
<script src="https://evil.example/blocked.js"></script>
<script>
  document.getElementById('marker').textContent = 'lib:' + (window.__t015Lib ? '1' : '0');
  fetch('https://evil.example/data.json').then(function () {
    document.getElementById('fetch').textContent = 'fetch:ok';
  }, function () {
    document.getElementById('fetch').textContent = 'fetch:blocked';
  });
  fetch('/api', { method: 'POST', body: '{}' }).then(function () {
    document.getElementById('api').textContent = 'api:ok';
  }, function () {
    document.getElementById('api').textContent = 'api:blocked';
  });
  try {
    parent.document.title;
    document.getElementById('parent').textContent = 'parent:ok';
  } catch (error) {
    document.getElementById('parent').textContent = 'parent:blocked';
  }
  try {
    var socket = new WebSocket('ws://' + location.host + '/ws');
    socket.onopen = function () { document.getElementById('ws').textContent = 'ws:opened'; };
    socket.onerror = function () { document.getElementById('ws').textContent = 'ws:blocked'; };
    socket.onclose = function () {
      if (document.getElementById('ws').textContent === 'ws:pending') document.getElementById('ws').textContent = 'ws:blocked';
    };
  } catch (error) {
    document.getElementById('ws').textContent = 'ws:blocked';
  }
  setTimeout(function () {
    if (document.getElementById('ws').textContent === 'ws:pending') document.getElementById('ws').textContent = 'ws:blocked';
  }, 500);
</script>"}

